/**
 * Deterministic mesh generators for Stage 3A-3B scaling.
 *
 * ONE FILE, TWO CONSUMERS. This module is served to the browser AND imported by
 * the Playwright test in Node, so the geometry a candidate sees in the browser
 * is generated by exactly the same code the test reasons about. A second
 * implementation would be a second source of truth and could diverge silently —
 * which is how Stage 3A-2 produced fabricated evidence twice.
 *
 * NO DEPENDENCIES, NO RANDOMNESS. Every generator is a closed form of its
 * parameters, so a size is reproducible on any machine.
 *
 * ROLE-APPROPRIATE BY CONSTRUCTION. The spec forbids measuring a candidate by
 * feeding it input its role rejects. These produce:
 *   - `uvSphere` / `torus`  : closed 2-manifold solids, for Manifold booleans
 *   - `openedSphere`        : a 2-manifold surface WITH one boundary loop, for
 *                             PMP hole filling
 *   - `crackedGrid`         : two sheets separated by an exact gap, for
 *                             Geogram's explicit tolerance path
 * None of them is malformed garbage built to make a candidate fail.
 */

/** Bytes a transfer representation occupies: Float64 positions + Uint32 indices. */
export function transferBytes(vertexCount, triangleCount) {
  return vertexCount * 3 * 8 + triangleCount * 3 * 4;
}

/**
 * A UV sphere: closed, 2-manifold, consistently wound outward.
 *
 * Poles are single vertices with triangle fans, and the seam reuses column 0's
 * vertices rather than recomputing the angle at 2*pi — `Math.cos(2*pi)` is not
 * bit-identical to `Math.cos(0)`, and the difference would leave a seam of
 * boundary edges instead of a closed shell. The corpus hit exactly this bug in
 * `openTube`, so it is avoided by construction here too.
 */
export function uvSphere(segments, rings, radius = 1, centre = [0, 0, 0]) {
  const positions = [];
  const triangles = [];

  positions.push(centre[0], centre[1], centre[2] + radius);
  for (let ring = 1; ring < rings; ring += 1) {
    const phi = (ring / rings) * Math.PI;
    const z = Math.cos(phi) * radius;
    const r = Math.sin(phi) * radius;
    for (let segment = 0; segment < segments; segment += 1) {
      const theta = (segment / segments) * Math.PI * 2;
      positions.push(
        centre[0] + Math.cos(theta) * r,
        centre[1] + Math.sin(theta) * r,
        centre[2] + z,
      );
    }
  }
  positions.push(centre[0], centre[1], centre[2] - radius);

  const north = 0;
  const south = 1 + (rings - 1) * segments;
  const at = (ring, segment) => 1 + (ring - 1) * segments + (segment % segments);

  for (let segment = 0; segment < segments; segment += 1) {
    triangles.push(north, at(1, segment), at(1, segment + 1));
  }
  for (let ring = 1; ring < rings - 1; ring += 1) {
    for (let segment = 0; segment < segments; segment += 1) {
      const a = at(ring, segment);
      const b = at(ring, segment + 1);
      const c = at(ring + 1, segment + 1);
      const d = at(ring + 1, segment);
      triangles.push(a, d, c, a, c, b);
    }
  }
  for (let segment = 0; segment < segments; segment += 1) {
    triangles.push(south, at(rings - 1, segment + 1), at(rings - 1, segment));
  }

  return { positions: new Float64Array(positions), triangles: new Uint32Array(triangles) };
}

/**
 * A torus: closed, 2-manifold, genus 1.
 *
 * Used as the second boolean operand because a genus-1 solid overlapping a
 * sphere forces genuine intersection work rather than a trivial containment
 * answer.
 */
export function torus(major, minor, majorSegments, minorSegments, centre = [0, 0, 0]) {
  const positions = [];
  const triangles = [];

  for (let i = 0; i < majorSegments; i += 1) {
    const u = (i / majorSegments) * Math.PI * 2;
    for (let j = 0; j < minorSegments; j += 1) {
      const v = (j / minorSegments) * Math.PI * 2;
      const r = major + minor * Math.cos(v);
      positions.push(
        centre[0] + Math.cos(u) * r,
        centre[1] + Math.sin(u) * r,
        centre[2] + minor * Math.sin(v),
      );
    }
  }

  const at = (i, j) => (i % majorSegments) * minorSegments + (j % minorSegments);
  for (let i = 0; i < majorSegments; i += 1) {
    for (let j = 0; j < minorSegments; j += 1) {
      const a = at(i, j);
      const b = at(i + 1, j);
      const c = at(i + 1, j + 1);
      const d = at(i, j + 1);
      triangles.push(a, b, c, a, c, d);
    }
  }

  return { positions: new Float64Array(positions), triangles: new Uint32Array(triangles) };
}

/**
 * A sphere with its north polar cap removed: 2-manifold WITH one boundary loop.
 *
 * This is PMP's role — a manifold surface with a boundary it can legitimately
 * fill — not a broken mesh. The removed cap leaves exactly one simple loop.
 */
export function openedSphere(segments, rings, radius = 1) {
  const sphere = uvSphere(segments, rings, radius);
  const kept = [];
  for (let t = 0; t < sphere.triangles.length; t += 3) {
    // Drop the north fan, which is the first `segments` triangles.
    if (t / 3 < segments) continue;
    kept.push(sphere.triangles[t], sphere.triangles[t + 1], sphere.triangles[t + 2]);
  }

  // Re-index so the now-unused pole vertex does not travel as an isolated point.
  const remap = new Map();
  const positions = [];
  const triangles = [];
  for (const original of kept) {
    let mapped = remap.get(original);
    if (mapped === undefined) {
      mapped = remap.size;
      remap.set(original, mapped);
      positions.push(
        sphere.positions[original * 3],
        sphere.positions[original * 3 + 1],
        sphere.positions[original * 3 + 2],
      );
    }
    triangles.push(mapped);
  }
  return { positions: new Float64Array(positions), triangles: new Uint32Array(triangles) };
}

/**
 * Two grid sheets separated along X by an exact gap — R19's defect at scale.
 *
 * The gap is the whole point: below it a tolerance must not weld, above it a
 * tolerance must. Vertices are computed from grid position so neighbours share
 * bit-identical coordinates and the recovered topology is genuinely connected
 * within each sheet.
 */
export function crackedGrid(side, gap) {
  const positions = [];
  const triangles = [];
  const base = (originX) => {
    const first = positions.length / 3;
    for (let row = 0; row <= side; row += 1) {
      for (let col = 0; col <= side; col += 1) {
        positions.push(originX + col, row, 0);
      }
    }
    const at = (col, row) => first + row * (side + 1) + col;
    for (let row = 0; row < side; row += 1) {
      for (let col = 0; col < side; col += 1) {
        triangles.push(at(col, row), at(col + 1, row), at(col, row + 1));
        triangles.push(at(col + 1, row), at(col + 1, row + 1), at(col, row + 1));
      }
    }
  };
  base(0);
  base(side + gap);
  return { positions: new Float64Array(positions), triangles: new Uint32Array(triangles) };
}

/**
 * Sphere tessellation whose transfer size is closest to `targetBytes`.
 *
 * Searched rather than solved so the reported size is the real one. Returns the
 * parameters plus the exact byte count, which the caller records — "10 MiB"
 * with no actual figure beside it is the kind of claim this stage exists to
 * avoid making.
 */
export function sphereForBytes(targetBytes) {
  let best = null;
  for (let segments = 8; segments <= 4096; segments = Math.ceil(segments * 1.15)) {
    const rings = Math.max(4, Math.round(segments / 2));
    const vertexCount = 2 + (rings - 1) * segments;
    const triangleCount = 2 * segments + 2 * segments * (rings - 2);
    const bytes = transferBytes(vertexCount, triangleCount);
    const delta = Math.abs(bytes - targetBytes);
    if (best === null || delta < best.delta) {
      best = { segments, rings, vertexCount, triangleCount, bytes, delta };
    }
  }
  return best;
}
